//! A unit system built on yadc, generated by yadc-codegen.
//!
//! - `Qty<U, N>`: a quantity, its unit `U` (a `UcumUnit`) in its type, counted in `N`.
//! - The prefixes and the base units, constants here (`KILO`, `METRE`); each
//!   module's quantities (`Length<N>`, in the coherent unit by default) and units
//!   (`KILOMETRE`), each unit a constant: one of it.
//! - `dynamic`: `DynQty`, a quantity of a unit chosen at run time; and each
//!   module's unit enums, a choice among a quantity's units.
//! - One module per family, each a Cargo feature: `si`, `heat`, `iso1000`, `intcust`, `cgs`, `infotech`, `us`, `british`, `clinical`, `constants`, `misc`; and `dimensionless`,
//!   always present.
#![cfg_attr(not(feature = "std"), no_std)]
#![feature(generic_const_exprs)]
// A unit is a struct with `&'static str`s, as a const parameter.
#![feature(adt_const_params)]
#![feature(unsized_const_params)]
#![feature(const_trait_impl)]
#![feature(const_cmp)]
#![feature(const_default)]
#![feature(derive_const)]
#![feature(const_ops)]
#![feature(const_convert)]
// The dynamic type's const_derive_more impls drop their operands in `const` code.
#![feature(const_destruct)]
#![allow(incomplete_features)]
#![allow(clippy::excessive_precision)]
#![allow(clippy::approx_constant)]

pub mod exact;
pub use exact::Exact;
pub mod unit;
pub use unit::UcumUnit;

use core::ops::{Add, Div, Mul, Sub};

/// A quantity: its number, counted in the unit `U` its type names, in
/// numbers of type `N`; `IS_BASE` says whether `U` is a base unit or a
/// product of base units. Quantities of one unit add and compare; a product
/// is counted in the product of the units (`mass * acceleration` in
/// kg·m·s⁻², a `Force`). Every unit is a constant, one of it counted in
/// `Exact` (`KILOMETRE`): a number times it is a quantity (`2.0 *
/// KILOMETRE`), `From` converts between it and the base units of its
/// dimension, and a quantity of the plain number's unit is a number
/// (`f64::from(d / METRE)`).
#[derive(Copy, Clone, PartialEq, PartialOrd, Debug, const_derive_more::ConstOps)]
#[const_ops(one = UcumUnit::ONE, from(Exact => f64, f32, i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize))]
pub struct Qty<#[ops] const U: UcumUnit, N, const IS_BASE: bool>(N);

/// It serializes as just its number: the unit is the deserialization
/// target's.
#[cfg(feature = "serde")]
impl<const U: UcumUnit, N: serde::Serialize, const IS_BASE: bool> serde::Serialize
    for Qty<U, N, IS_BASE>
{
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        self.0.serialize(s)
    }
}

#[cfg(feature = "serde")]
impl<'de, const U: UcumUnit, N: serde::Deserialize<'de>, const IS_BASE: bool>
    serde::Deserialize<'de> for Qty<U, N, IS_BASE>
{
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        N::deserialize(d).map(Qty)
    }
}

impl<const U: UcumUnit, N, const IS_BASE: bool> Qty<U, N, IS_BASE> {
    /// Its unit.
    pub const fn unit(&self) -> UcumUnit {
        U
    }
}

impl<const U: UcumUnit, const IS_BASE: bool> Qty<U, Exact, IS_BASE> {
    /// One of the unit.
    pub const ONE: Self = Qty(Exact::ONE);
}

/// The number, a space and the unit: `2 km`, `9.81 N`.
impl<const U: UcumUnit, N: core::fmt::Display, const IS_BASE: bool> core::fmt::Display
    for Qty<U, N, IS_BASE>
{
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        self.0.fmt(f)?;
        f.write_str(" ")?;
        core::fmt::Display::fmt(&U, f)
    }
}

/// A condition on units, as a type: `Check<{ U.same_dimension(V) }>: True`
/// holds where `U` and `V` measure the same dimension.
pub struct Check<const B: bool>;

/// What a true `Check` is.
pub trait True {}
impl True for Check<true> {}

/// How a unit's numbers convert to and from base units, in numbers `N`:
/// `Check<false>` for a linear unit (`n · size + zero`), `Check<true>` for a
/// log unit (`reference · base^(n / per)`, so `N` is `Real`).
pub trait Conversion<N> {
    /// The number of base units `n` of `unit` is.
    fn to_coherent(unit: UcumUnit, n: N) -> N;
    /// The number of `unit` `x` base units is.
    fn from_coherent(unit: UcumUnit, x: N) -> N;
}

impl<N> Conversion<N> for Check<false>
where
    N: From<Exact> + Mul<Output = N> + Add<Output = N> + Sub<Output = N> + Div<Output = N>,
{
    fn to_coherent(unit: UcumUnit, n: N) -> N {
        unit.to_coherent(n)
    }
    fn from_coherent(unit: UcumUnit, x: N) -> N {
        unit.from_coherent(x)
    }
}

impl<N: num_traits::real::Real + From<Exact>> Conversion<N> for Check<true> {
    fn to_coherent(unit: UcumUnit, n: N) -> N {
        unit.log_to_coherent(n)
    }
    fn from_coherent(unit: UcumUnit, x: N) -> N {
        unit.log_from_coherent(x)
    }
}

/// A quantity of any unit in a base unit of its dimension, the one the
/// target type names: `let d: Length<f64> = (2.0 * KILOMETRE).into();`.
impl<const U: UcumUnit, const V: UcumUnit, N> From<Qty<U, N, false>> for Qty<V, N, true>
where
    N: From<Exact> + Sub<Output = N> + Div<Output = N>,
    Check<{ U.same_dimension(V) }>: True,
    Check<{ U.is_log() }>: Conversion<N>,
{
    fn from(q: Qty<U, N, false>) -> Self {
        Qty(
            V.from_coherent(<Check<{ U.is_log() }> as Conversion<N>>::to_coherent(
                U, q.0,
            )),
        )
    }
}

/// A quantity in a base unit in any unit of its dimension, the one the
/// target type names.
impl<const U: UcumUnit, const V: UcumUnit, N> From<Qty<V, N, true>> for Qty<U, N, false>
where
    N: From<Exact> + Mul<Output = N> + Add<Output = N>,
    Check<{ U.same_dimension(V) }>: True,
    Check<{ U.is_log() }>: Conversion<N>,
{
    fn from(q: Qty<V, N, true>) -> Self {
        Qty(<Check<{ U.is_log() }> as Conversion<N>>::from_coherent(
            U,
            V.to_coherent(q.0),
        ))
    }
}

/// The coherent units printed by name, not as their product of base units.
static NAMED: [(UcumUnit, &str); 0] = [];

